insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 1, 'How does chanDiagnosis decide which samples of a history are late?', '["It walks the log-log plot for the straight portion and opens the window where the trend becomes linear, which is why the four published histories share a single start time.", "It opens the window at the last rate change in the history, since a Chan line taken across a rate change is reading two wells rather than one.", "It sorts by time and keeps a trailing fraction of the sample count, so the default lateFraction of 0.5 keeps the last 20 of the golden''s 40 and opens the window at t = 186.345364 days.", "It opens the window where the ratio first clears minWor of 0.1, the threshold the module documents as the point below which there is no water problem to diagnose."]'::jsonb, 2, 'The rule is arithmetic on the sample count and nothing else. Nothing is reported about the samples used beyond the one start time of 186.345364 days.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 2, 'The published channelling, coning, displacement and flat histories all come back with lateFromT = 186.345364 days. Why?', '["Each carries 40 samples over the same times, and a window picked by counting lands on the same sample whatever shape the ratio has.", "Each one reaches boundary-dominated flow at that time, which is the condition a late window exists to satisfy.", "The value is copied out of the golden metadata, so every published history inherits the oracle''s series[20:] boundary instead of computing a window of its own.", "Each of their derivative fits first clears minSpanDecades of 0.4 at that sample, and the window opens where that gate is first satisfied."]'::jsonb, 0, 'The fraction applies to the sample count, so shape has no vote: the last 20 of 40 start at 186.345364 days on the channelling history and on the flat one alike.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 3, 'The teaching well returns a derivative slope of 1.229355999 read whole and 1.442132492 read at the default late half. What changed between the two readings?', '["The Bourdet derivative column was recomputed over the shorter window, which weights the late samples more heavily than the early ones.", "Nothing in the data. The wider window adds older samples whose derivative climbs less steeply, and least squares averages the two stretches together.", "The wide reading fell below minR2 of 0.5 on the derivative fit, so the engine reported the ratio slope in its place.", "The late half drops the stretch after the well was beaned back, and the whole history keeps those falling samples inside the derivative fit."]'::jsonb, 1, 'The same 38 samples produce both numbers, and channellingSlope of 1.3 falls between them, so one window reads displacement and the other channelling.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 4, 'An analyst types a lateFraction of 0.05 on the teaching well, expecting it to be rejected. What comes back?', '["An error object naming the range the module will accept, since a fraction it cannot use is refused rather than quietly replaced with one it can.", "The documented default of 0.5 put in its place, which opens the window at 250.242976 days and returns the channelling verdict with an ambiguous flag.", "A reading flagged ambiguous, because a window that narrow leaves the derivative slope inside the ambiguous band of 0.25 around the channelling boundary.", "A reading with ok true, computed on the floor of 0.10: the window opens at t = 2308.407093 days and the mechanism is coning."]'::jsonb, 3, 'The clamp is documented nowhere: not in the return object, not in a note and not in a warning. Every fraction at or below 0.10 reports the same start of 2308.407093 days.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 5, 'From a returned result alone, what tells a reader that the window fraction typed into the call was replaced by another one?', '["A warnings array carrying the substituted value beside the one that was handed in.", "Identical values of lateFromT across different typed fractions, since 0.10 and below all report 2308.407093 days on that teaching history and 1.00 and above all report 15.000000 days.", "Nothing does, because the fraction is echoed back in a field of its own for exactly this purpose.", "The ambiguous flag, which the module raises whenever any input has been coerced."]'::jsonb, 1, 'The fraction appears in no field of the object, so a start time in days is the only trace, and identical start times across different typed values are the signature.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 6, 'On the clamped floor window of the teaching well no positive derivative survives. What does the call refuse there, and what does it hand back anyway?', '["It refuses the whole reading and returns ok false on the words that six producing samples are the bare minimum for a Chan reading.", "It refuses the fraction that was typed, which is why the window start moves out to 2308.407093 days on that history.", "It refuses the slope, so derivativeSlope, derivativeR2 and spanDecades are all absent, and it still returns a named mechanism, a note and a start time.", "It refuses nothing at all and quietly falls back on the ratio slope of 0.143809349 in place of the missing derivative slope."]'::jsonb, 2, 'A verdict of coning comes back with no derivative fit under it, and coning is not treatable, so a water shutoff is refused off a reading that measured no slope.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 7, 'A report states that water broke through at 186.345364 days, citing lateFromT. What is wrong with the sentence?', '["lateFromT is the timestamp of whichever sample the count landed on, so it records the length of a spreadsheet rather than an event in the reservoir.", "Nothing at all, provided the derivative fit taken over that window cleared minR2 of 0.5, which is the gate that certifies a late reading as a measurement rather than as scatter.", "The figure belongs to the teaching well this course built for itself rather than to the four published histories, and only a published history carries a date a report may quote.", "Breakthrough is a ratio, so the last sample ratio was the number to quote."]'::jsonb, 0, 'The start is never checked against anything physical: nothing tests that it sits in boundary-dominated flow, that the rate held steady, or that it is late at all.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 8, 'The published flat history returns lateFromT = 186.345364 days, worSlope = 0.000000000 and a derivative fit with ok false and n = 0. What does that start time establish?', '["That the window cleared minSpanDecades of 0.4, since a span is required before any start time is issued at all.", "That 20 samples were fitted on it, since the field is populated only once a fit has actually succeeded.", "That the ratio really was flat across it, since the field is filled in from the samples the accompanying note describes.", "That a window was selected."]'::jsonb, 3, 'A start time proves a window was chosen by counting. No slope, no fit quality and no span came back on that history, and a mechanism of displacement was named anyway.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 9, 'Which input does chanDiagnosis refuse outright, and which does it accept without question?', '["It refuses a window fraction outside the range it can use, and accepts a history of any length above three samples.", "It refuses a history of fewer than six samples with ok false and every slope absent, and it accepts any window fraction whatever.", "It refuses a window that does not sit in boundary-dominated flow, and accepts whatever sample count the history happens to carry underneath that window.", "It refuses neither: a five sample history comes back with ok true and indeterminate in place of a mechanism."]'::jsonb, 1, 'On five samples the return is ok false, mechanism indeterminate, every slope n/a and the words that six producing samples is the bare minimum. No fraction is ever refused.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 10, 'Across the sweep from 0.20 to 1.00 the derivative slope on the teaching well moves by 0.370920348. What must that figure be read against?', '["The ambiguous band of 0.25, which the sweep never leaves, so the reading stays flagged from one end of the dial to the other.", "The minimum span of 0.4 log cycles, on the reasoning that a slope moving less than the span gate cannot move a verdict.", "The margin carrying the recommendation, which at the default window is 0.142132492 above the channelling boundary of 1.3.", "The gap of 1.514312e-2 between least squares and Theil-Sen on the published coning history, which is the estimator error inside the fit."]'::jsonb, 2, 'The dial is worth more than twice the margin the spend is decided on, and it is an untyped analyst choice with a default of 0.5 and no guidance anywhere.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 11, 'Two wells have the same producing life and different reporting schedules. What does one lateFraction give them?', '["The same window, because the fraction is applied to producing time rather than to the samples that record it.", "The same window, because the sample count is normalised by the span in log cycles before the fraction is applied to it.", "Different windows only where one of them fails minSpanDecades of 0.4, which is the one gate that lets a reporting schedule matter.", "Different windows, and nothing in the object says so."]'::jsonb, 3, 'The fraction is applied to the sample count, so the window opens at whichever sample the count lands on, and the only field recording it is a start time in days.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 12, 'The sweep row at lateFraction 0.80 gives a derivative slope of 1.292632524 and reads displacement, while 0.70 gives 1.336892539 and reads channelling. What separates those two rows?', '["A shortfall of 0.007367476 against the channelling boundary of 1.3, and that one comparison.", "A derivative fit quality of 0.995879922, under the minR2 the branch wants.", "A count of 31 late samples, since confidence drops and the mechanism softens once the window holds most of the history.", "A reported span of 1.672580873 log cycles, which is longer than the stretch the classifier will accept as late."]'::jsonb, 0, 'A margin of 0.007367476 on a log-log slope is far below what a production allocation can resolve, and the water shutoff turns from candidate to blocked across it.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 13, 'Which field of the returned object records the window fraction that produced the reading?', '["spanDecades, which is that same window expressed in log cycles rather than in days.", "None of them, and spanDecades is not it: at the default that field reads 0.900620470 while the window itself runs 1.157940604 log cycles.", "The confidence, which is dropped to low whenever a fraction other than the documented default of 0.5 was used, so that a tuned window announces itself in the object.", "The note, which names the fraction whenever it differs from the default of 0.5."]'::jsonb, 1, 'The fraction appears nowhere in the object. The window start in days is the only trace of the choice, and spanDecades describes the derivative fit instead.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 14, 'What does the module test about the late window itself before it reads a mechanism off it?', '["That the window covers at least 0.4 log cycles, which is exactly what minSpanDecades is written for.", "That the window holds at least 20 samples, the count each of the four published histories carries at the default, below which a mechanism is not named at all.", "Nothing: it never tests that the window is late, that the rate held steady across it, or that the verdict is stable against the fraction.", "That the window sits in boundary-dominated flow, which is the reason lateness is asked for in the first place."]'::jsonb, 2, 'The one span test is applied to the span the derivative fit reports rather than to the window that was selected, and on the published histories that fit reports 1.206802663 log cycles.'),
  ('intervention', 'intermediate', 'module', 'm01-the-late-window', 15, 'On the published coning history the engine slope and the published slope differ by 1.514312e-2, while on channelling and displacement they agree to 2.220446e-16 and 4.440892e-16. What accounts for the coning row?', '["That shape is not a power law over that window, so least squares and the median of every pairwise slope weight a curved log-log trend differently.", "Scatter in the coning history, which the median of pairwise slopes resists and ordinary least squares does not.", "The oracle reads its late window as series[20:] while the engine at 0.5 opens one sample earlier, so the two fits sit on different samples.", "The coning fit falls below minR2 of 0.5, so the engine quietly substitutes the ratio slope of 0.230022389 while the published figure stays a derivative slope."]'::jsonb, 0, 'There is no noise in the series at all. The two routes agree to machine precision on the two power-law shapes and part in the second decimal on the curved one.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 1, 'One call on the teaching well at the default window returns worSlope = 1.040602176 and derivativeSlope = 1.442132492. What samples was each of them fitted on?', '["Both over the same 19 late samples, with the derivative slope taken as the difference of successive ratio points inside that window.", "The ratio slope over all 19 late samples, the derivative slope over only the 15 of them whose derivative is above zero.", "The ratio slope over the whole 38 sample history and the derivative slope over the 19 samples of the late window alone.", "Both over the 15 samples that survive the positive-derivative filter, so the two fits sit on identical data over an identical span."]'::jsonb, 1, 'Two fits on two different sets of samples come back side by side, 0.401530316 apart, and nothing in the object says they were measured on different data.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 2, 'spanDecades comes back as 0.900620470 on that reading. What is it the span of?', '["The late window, which is the stretch of history the whole diagnosis is reported against.", "The ratio fit, since the ratio slope is the one fitted over every late sample in the window.", "The derivative fit alone, which is 0.257320134 of a log cycle shorter than the 1.157940604 log cycles the window itself runs.", "The whole history handed in, which on the teaching well is 2.380211242 log cycles from the first sample to the last."]'::jsonb, 2, 'It is the only span in the object and it is named as though it described the reading, while it describes the shorter of the two fits inside it.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 3, 'At lateFraction 0.20 the window runs 0.450310235 log cycles and at 0.25 it runs 0.578970302, both longer than minSpanDecades of 0.4, yet neither reading reports a span at all. Why?', '["The gate is applied to the span the derivative fit reports after the falling samples are dropped, not to the window that was selected.", "Both windows hold fewer than the six producing samples a Chan reading is refused below, so no fit was attempted on either.", "Both derivative fits fell under minR2 of 0.5, and a fit that fails the quality gate has its span nulled along with its slope.", "Spans are reported only once the mechanism is named, and at those two fractions the mechanism came back indeterminate."]'::jsonb, 0, 'Dropping the contrary samples shortens the fit by 0.257320134 of a log cycle, so a reader who checks the window against 0.4 passes two windows the fit then fails.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 4, 'The published coning history returns a ratio slope of 0.230022389 at a fit quality of 0.930741260, which is still climbing, and the verdict is coning. What produced that verdict?', '["The ratio fit quality of 0.930741260, which falls too far under a clean fit for the climbing reading to be trusted at all.", "The disagreement between the two slopes, which the classifier reads as the signature of a cone that has reached the perforations.", "The published late derivative slope of -0.555098339661, which the classifier reads out of the golden metadata rather than fitting for itself.", "The derivative slope of -0.539955222, which is the only slope compared against a threshold."]'::jsonb, 3, 'coningSlope is -0.1 and the derivative sits below it. A reader watching only the ratio would have said the water is still getting worse.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 5, 'On the teaching well the ratio slope of 1.040602176 sits below the channelling boundary and the derivative slope of 1.442132492 sits above it. What does the classifier do with that?', '["It averages the two and compares the result against 1.3, which is why the reading comes back flagged as ambiguous.", "It reads channelling off the derivative slope alone and never consults the ratio slope beside it.", "It reports the disagreement in a field of its own, since two slopes that straddle a threshold are the definition of an ambiguous reading.", "It takes the slope with the better fit quality, which here is the derivative at 0.998513658 against the ratio at 0.921895186."]'::jsonb, 1, 'The mechanism follows one comparison. There is no test that the two slopes agree and no flag when they differ by 0.401530316 as they do here.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 6, 'The engine''s own note concedes something about the boundary between displacement and channelling. What is it?', '["The derivative of a power law is offset from the ratio by a constant, so the boundary has to sit above 1 to keep the two pictures apart.", "A ratio measured in stb/stb and a derivative measured per log cycle cannot be compared against one threshold without rescaling one of them.", "For any power-law history the ratio and its derivative carry the same log-log slope, so nothing separates the two pictures except how steep the climb is.", "The boundary was fitted to field cases rather than chosen, so it moves whenever the module is calibrated against a new set of wells."]'::jsonb, 2, 'On the published channelling and displacement histories the two slopes are identical to the digit, at 1.600000000 and at 1.000000000, which is the concession made visible.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 7, 'What is the ambiguous band a distance from, and how wide is it?', '["It is 0.25 either side of channellingSlope, so on the derivative slope it runs from 1.050000 to 1.550000, a width of 0.500000.", "It is 0.25 either side of whichever threshold the reading came closest to, so it moves with the mechanism that was named.", "It is 0.25 of the derivative fit quality, so any fit falling that far under a perfect fit is returned flagged whatever slope it carried.", "It is 0.25 of a log cycle on the reported span, so a short fit is flagged and a long one is not."]'::jsonb, 0, 'The flag is a distance from a fixed number and is not a statement about the data: a slope of 1.442132492 is 0.142132492 from 1.3 and is flagged.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 8, 'A demonstration series at a derivative slope of 1.150000000 is flagged ambiguous and the published displacement history at 1.000000000 is not, and both fit their data at a quality of 1.000000000. What moved the flag?', '["The scatter in the demonstration series, which the fit quality of 1.000000000 reports on the ratio rather than on the derivative.", "The sample count behind each reading, since the published history carries 20 late samples and the demonstration far fewer than that.", "The confidence attached to each, which the classifier assigns first and then uses to decide whether to raise the ambiguous flag.", "Only the distance to 1.3."]'::jsonb, 3, 'Neither fit has any scatter in it whatever. The flag fired because 1.150000000 is closer to 1.3 than 1.000000000 is, and it fires on nothing else.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 9, 'Where is the ambiguous band never applied?', '["At the channelling threshold of 1.3, which carries the confidence label instead of the flag.", "At the coning threshold of -0.1, so a derivative slope just below it is called coning and blocked with no ambiguity reported.", "At minR2 of 0.5, where a fit quality landing near the gate is passed or refused with nothing said about how near it came.", "At minSpanDecades of 0.4, where a reported span landing near the gate is passed or refused with nothing said about how near it came."]'::jsonb, 1, 'The band exists on the boundary that recommends the spend and not on the one that refuses it: below -0.1 the shutoff is blocked and the reading comes back clean.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 10, 'Four teaching rows return derivative fit qualities from 0.999944740 down to 0.998513658 and every one is called low confidence, while the published coning history at 0.948751314445 is called high. What is confidence tracking?', '["The fit quality itself, compared against minR2 of 0.5, which the four teaching rows clear by so much that they are rounded down.", "The count of late samples behind the fit, which is why a window holding 19 samples reads lower than one holding 20.", "The ambiguous flag, which is a distance from 1.3 inside a band of 0.25, so a slope near a threshold is low and one away from a threshold is high.", "The agreement between the published slope and the engine slope, which on the coning history is 1.514312e-2 and on the teaching well is not published at all."]'::jsonb, 2, 'The best fit in the group earns the worse label. Confidence says where a slope landed relative to a threshold, not how well the line fitted.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 11, 'Downstream of the diagnosis, where is the confidence word actually read?', '["In one place only: the third reason on a water shutoff returned as a candidate off a channelling reading, which asks for a production log before the squeeze.", "In every block reason, which quotes the confidence beside the mechanism that produced the block.", "In the ranking, which sorts a low confidence candidate below a high confidence one inside the same verdict band, so the ordered list carries the caveat instead of the reasons.", "Nowhere at all, since confidence is a label for the reader and the screening reads only numbers."]'::jsonb, 0, 'The verdicts that block a treatment read neither the confidence nor the ambiguous flag, so the caveat is attached to the recommendation that spends money and not to the one that refuses to.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 12, 'The published flat history comes back with a mechanism of displacement and a confidence of n/a. What does a reader take from the missing word?', '["That the reading was refused, since a diagnosis without a confidence is not a diagnosis the module is willing to stand behind.", "That no fit survived to be confident about, though the note beside it reads as an unremarkable well with nothing for an intervention to fix.", "That the confidence was suppressed because the ambiguous flag had fired, which is the one condition under which this module leaves the field empty.", "That the history cleared every gate and needed no qualifier, which is the only case in the module where the field is omitted."]'::jsonb, 1, 'The derivative fit returned ok false with n = 0 and a mechanism was named anyway, so an absent confidence reads as reassurance rather than as a warning.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 13, 'Four gates fire before a mechanism is named. Which is the one that is applied to a single sample?', '["minR2 at 0.5, applied to the final derivative point.", "minSpanDecades at 0.4, compared against the interval between the last two samples in the window.", "The six sample minimum, which counts backwards from the last sample until it reaches the start of the late window.", "minWor at 0.1, compared against the last sample ratio alone."]'::jsonb, 3, 'A demonstration series climbing to 20.279117393 with its final reading replaced by a post shut-in test of 0.060000000 comes back with no slope, no span and no confidence.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 14, 'What does the module do when the derivative fit falls below minR2 of 0.5, and how does it word it?', '["It returns the slope anyway with the ambiguous flag raised beside it, since a derivative fit with too much scatter in it is exactly the case that flag was written to mark for a reader.", "It falls back on the ratio slope, which is fitted over more samples and therefore over a longer span.", "It refuses to read a mechanism off the slope, on the words that the fit explains only 0.0 percent of it, so a fraction in the object is quoted as a percentage in the message.", "It widens the late window one sample at a time until the derivative fit clears the gate, and then reports the window fraction it ended on so that the reading can be reproduced."]'::jsonb, 2, 'Fit quality is a fraction in this engine and a percentage in its own error text, so the same quantity is printed two ways in one module.'),
  ('intervention', 'intermediate', 'module', 'm02-the-diagnosis', 15, 'Which parts of this module has an independent route ever checked?', '["The log-log slope, checked by the median of every pairwise slope, and the skin multiplier, checked by a full radial Darcy rate built in SI. Both are pure arithmetic.", "The mechanism and the confidence, which the golden publishes for each of its four labelled histories alongside the late derivative slope that each of those histories also carries.", "The block reason, which the golden publishes for every one of its four labelled histories whose water shutoff squeeze comes back refused by the screening.", "Nothing at all, since the published file carries four labelled histories, five skin pairs, one geometry floor and one power law, and no expected value for anything."]'::jsonb, 0, 'The published power law comes back at a difference of 0.0000e+0 on a slope of 1.350000000000, while chanDiagnosis, screenTreatments, rankTreatments and skinFromPiRatio are asserted against nothing.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 1, 'What is the quantity skinPiMultiplier returns?', '["The productivity index after the job, in the same units the well is producing in before it.", "The denominator before the job over the denominator after it, each being ln(re/rw) less 3/4 plus that skin.", "The rate the well will make once the treatment is placed, divided by the rate it makes today, at the drawdown that was entered with the geometry.", "The fraction of the original rate that damage is costing, which on the published geometry at a skin of 8.000 is 0.496878274."]'::jsonb, 1, 'It is one dimensionless group divided by another and it forms no rate at all. Productivity is inversely proportional to that group, so the ratio inverts.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 2, 'On the published geometry a twentyfold change in drainage radius, from 500 ft to 10000 ft, moves the zero-skin denominator by 2.995732274. What does that establish?', '["That the radii matter little and the skin matters a lot, because the ratio enters through a logarithm and the skin is added undivided.", "That the drainage radius has to be known to within a factor of two before a multiplier can be quoted at all.", "That the pseudo-steady-state constant of 3/4 dominates the group, since it is the only term that does not move with the radii.", "That the group is insensitive to everything, which is why the published multipliers agree with an independent route to machine precision."]'::jsonb, 0, 'One unit of skin more than covers a twentyfold error in the drainage radius, so a guessed radius is forgivable and a mis-measured skin is not.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 3, 'The published pair with skin 0.000 before and 0.000 after returns a multiplier of 1.000000000000 with a departure from one of 0.0000e+0. Why is that row worth having?', '["It fixes the pseudo-steady-state constant at 3/4, which is the only term that survives when the two skins are equal.", "It shows that an untreated well is worth treating, since the multiplier never falls below one on the published geometry.", "It is one number divided by itself, so any implementation that cannot reproduce it bit for bit has an error term somewhere in the group.", "It is the only published pair whose value the oracle computes by dividing two real flow rates rather than two dimensionless groups."]'::jsonb, 2, 'The identity is the cheapest possible gate on the arithmetic, and the departure from one is 0.0000e+0 rather than something small.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 4, 'The published multipliers were produced twice, by two routes. What were they?', '["A Theil-Sen fit through the five published skin pairs and an ordinary least squares fit through the same five, which agree on a clean geometry.", "The engine run at the published geometry and the same engine run at a drainage radius of 500 ft, with the difference reported as a sensitivity.", "A field measured productivity index before and after a real acid job, compared against what the group predicted for that same job.", "A full radial Darcy rate in SI on one side and a ratio of two dimensionless groups on the other."]'::jsonb, 3, 'The oracle builds two real flow rates with permeability in square metres and pressures in pascals; the engine never forms a rate. They hold to machine precision across all five pairs.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 5, 'Removing one unit of skin buys 3.717372 percent starting from a skin of 20.0 and 12.657067 percent starting from 1.0, on the same published geometry. What makes the difference?', '["The flow efficiency, which is measured against an undamaged well and therefore rises faster once the well is nearly clean.", "The denominator is a sum, so one unit is a larger share of a small denominator than of a large one.", "The logarithm of the radius ratio, which is 8.650724584041 and swamps a single unit of skin only while the skin itself is small.", "The pseudo-steady-state constant of 3/4, which is subtracted once and so weighs more heavily against a small skin than against a large one."]'::jsonb, 1, 'A stimulation on a lightly damaged well buys the most per unit of skin, and one on a badly damaged well buys the most in total because it removes so many units.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 6, 'A vendor reports that a treatment delivered a 12.657067 percent uplift and offers it as the treatment''s performance. What is wrong with that?', '["Nothing, provided the geometry is quoted beside it, since the drainage and wellbore radii are what set the size of an uplift.", "An uplift in percent cannot be compared across wells at all, because the multiplier is a ratio and a ratio does not convert into a percentage.", "The figure describes the well it was done on, not the job: the same unit of skin on a well at 20.0 would have shown 3.717372 percent.", "The number is a flow efficiency rather than a multiplier, and flow efficiency is measured against an undamaged well rather than against this one."]'::jsonb, 2, 'Both figures are one unit of skin removed on one published geometry. Only the starting skin differs, and the starting skin is a property of the well.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 7, 'On the teaching geometry the flow efficiency before treatment is 0.495348054 and a designed acid job returns a multiplier of 2.879215612184. What is each measured against?', '["The flow efficiency against an undamaged well, so it says how much is being lost, and the multiplier against the well as it stands, so it says what the job changes.", "Both against an undamaged well, which is why the flow efficiency after the job comes back at 1.426213850 rather than at 1.", "Both against the well as it stands, so the two can be multiplied together to give the rate the well will make after the job.", "The flow efficiency against the well as it stands and the multiplier against a well at the geometry floor of -7.361728083."]'::jsonb, 0, 'Neither is a rate. The denominator falls from 14.861728083 to 5.161728083 and the flow efficiency after the job is 1.426213850, above one because a negative skin beats no skin at all.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 8, 'A claimed uplift of 2.000 times implies a post-job skin of -3.680864042 on the teaching geometry, and a claimed 12.000 times implies -6.748250743. Why does a sixfold larger claim move the skin so little?', '["Because skinFromPiRatio clamps its answer at the geometry floor of -7.361728083, so every large claim is pushed back towards it.", "Because the logarithm of the radius ratio compresses the answer, so a claim stated in fold terms cannot resolve a skin below about -6 on any geometry.", "Because the inverse is fitted rather than solved, and the fit was built on the five published skin pairs, none of which reaches a skin that deep.", "The multiplier is a ratio of two denominators and the second one is running out of room."]'::jsonb, 3, 'Large claims are cheap in fold terms and expensive in skin terms, which is why the skin is the number worth arguing about.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 9, 'A claimed uplift of 6.000 times on the teaching geometry implies a post-job skin of -6.134773403. What does the module do about it?', '["It returns the number with a warning naming the achievable range, which is the one plausibility check this function carries.", "It refuses, because the implied skin is past the deepest figure the module calls real for a fracture.", "It returns the number with no flag, no warning and no note, though its own refusal text puts a fracture at about -5 to -6.", "It returns the number and sets the ok flag on the result to false, leaving the caller to decide whether to use it."]'::jsonb, 2, 'The plausibility limit exists only in a sentence inside a different function''s error message. The geometry floor here is -7.361728083 and nothing between the two limits is remarked on.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 10, 'What check has skinFromPiRatio ever been put through?', '["A Theil-Sen route written by the oracle, the median of every pairwise slope, which is the same independent estimator it turns on the log-log slope.", "A round trip on the published pairs run by the teaching digest: case 2 inverts to -2.000000000 at a difference of 8.8818e-16.", "A radial Darcy rate in SI written by the oracle, which is the route that checks the multiplier it inverts.", "The five published skin pairs, each one of which carries an expected implied skin printed in the golden beside its published multiplier."]'::jsonb, 1, 'The oracle asserts skinPiMultiplier and asserts skinFromPiRatio against nothing at all, so the round trip is a check this course ran rather than one anybody wrote.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 11, 'How does skinFromPiRatio report a wellbore radius larger than the drainage radius, a negative claimed ratio, or a claimed ratio of zero?', '["As a bare NaN with no ok flag and no error text, so a caller that skips a finite check cannot tell a refusal from an answer.", "As an object carrying ok false and an error string naming the radii, which is the failure contract this module uses throughout.", "As a multiplier of 1.000000000000, which is the value the group returns whenever the skin does not change.", "As the geometry floor of -7.361728083, which is the deepest skin the geometry admits and therefore the safest fallback."]'::jsonb, 0, 'pssDenominator, minimumSkin and skinFromPiRatio all return a bare NaN, and skinPiMultiplier returns an object with an ok flag. Two failure contracts in one module.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 12, 'Where does skinPiMultiplier actually refuse a design?', '["Wherever the after-skin passes the range its own error text calls real, which is about -3 to -5 on acid and -5 to -6 on a fracture.", "Wherever the multiplier exceeds the largest published value of 4.060771880315, above which no treatment on record has ever delivered.", "Only where the denominator reaches zero and the productivity index goes infinite, which on the teaching geometry is a skin of -7.361728083.", "Wherever the after-skin is deeper than the before-skin by more than the flow efficiency of the untreated well can support."]'::jsonb, 2, 'An after-skin of -6.800 returns 26.457156986 with warnings none and notes none, so clearing the guard means one thing only: the equation still has a denominator.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 13, 'An after-skin of -7.400 on the teaching geometry is refused with the words that taking the skin to -7.4 would put it below the -7.4 this geometry allows. What has gone wrong in that sentence?', '["The floor quoted is the one for the published geometry rather than for the teaching geometry, which allows a deeper skin than that.", "The message names a fracture limit of about -5 to -6 that has nothing to do with the comparison that actually refused the design.", "The request was accepted and the message was printed anyway, since the ok flag on that result comes back true at every after-skin.", "The request and the floor are printed at the same rounding, so the message appears to compare a number against itself."]'::jsonb, 3, 'The floor is -7.361728083. Rounded to one decimal the request and the limit are both -7.4, and the reader is left with no way to see how far past the limit the design sat.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 14, 'On the teaching geometry an after-skin of -5.000 returns 6.292734624 and one of -6.800 returns 26.457156986. What separates those two answers?', '["A warning attached to the deeper row, since -6.800 is past the -5 to -6 the module calls real for a fracture.", "A factor of 4.204397383, handed back with the same confidence as the honest one and with warnings none on both rows.", "A refusal on the deeper row, since 26.457156986 is above every multiplier the five published pairs contain.", "A different geometry, since a multiplier that large requires the published drainage radius of 2000.000000 ft rather than the teaching one."]'::jsonb, 1, 'The deeper row sits past everything the module''s own refusal text calls achievable and is accepted in silence, 0.561728083 above the floor.'),
  ('intervention', 'intermediate', 'module', 'm03-what-removing-skin-is-worth', 15, 'minimumSkin is computed on every call to skinPiMultiplier and returned inside the successful result. What is it compared against?', '["Nothing but zero, in the test of whether the denominator has run out, and it is never set against the after-skin that was asked for.", "The after-skin, which is why an unreachable design comes back refused with the floor quoted in the message.", "The before-skin, which is refused with a different sentence saying that is the equation running out rather than a well.", "The achievable range of about -3 to -5 on acid and -5 to -6 on a fracture, which is where the plausibility check lives."]'::jsonb, 0, 'It is present in the result and unused: on the teaching geometry it reads -7.361728083 beside a multiplier of 26.457156986 with no comment on the distance between them.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 1, 'What comes back from one call to screenTreatments?', '["The treatment the well should have, chosen from the seven by the mechanism the diagnosis returned.", "A verdict and between one and three reason strings for every one of the seven treatments, whether or not any of them applies.", "The three treatments whose gates the well row cleared, ordered by the size of the uplift each would deliver at the skin that was entered.", "A verdict for each treatment that addresses the mechanism named, with the rest of the catalogue left out of the result entirely."]'::jsonb, 1, 'It chooses none of them and prices none of them. On the teaching well three come back candidate at once, three consider and one no.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 2, 'rankTreatments hands the seven back in an order. What is that order built from?', '["The uplift each treatment would buy, computed from the skin on the well row and the geometry handed in beside it.", "The confidence of the diagnosis, so that a low confidence reading pushes every treatment it gated further down the list.", "The count of reasons behind each verdict, so a treatment argued in three sentences outranks one argued in a single sentence.", "The verdict enumeration, with ties broken by the order the treatments were pushed in the source."]'::jsonb, 3, 'The order runs candidate, consider, marginal, blocked, unknown, no, and nothing about the well breaks a tie. Position is not priority.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 3, 'The water cut is swept and the shutoff reads no with 1 reason at 29.0 percent and candidate with 3 reasons at 30.0 percent, with the diagnosis held fixed. What does that show?', '["That the diagnosis is recomputed at each water cut, since the reason count follows the mechanism.", "That the two extra reasons at 30.0 percent are the plumbing argument and the block reason.", "That the water cut gate fires before the mechanism is read, so a channelling reading buys nothing under 30.0 percent.", "That the gate sits where a channelling reading becomes more likely than a coning one."]'::jsonb, 2, 'Nothing in the refused rows is a statement about water movement. It is a policy threshold, crossed by a number that is itself a ratio of two allocated rates.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 4, 'In the water cut sweep, which column moves between 60.0 percent and 61.0 percent?', '["The fracture reason count, from 2 to 3, when the out of zone growth warning is added.", "The water shutoff verdict, which turns from no into candidate as the gate opens.", "The artificial lift verdict, which turns from no into consider once the column is heavy enough to be worth sizing.", "The water shutoff reason count, from 1 to 3, when the plumbing argument and the confidence caveat are both appended."]'::jsonb, 0, 'Three thresholds sit in those nine rows: the shutoff opens at 30.0 percent, the fracture warning appears between 60.0 and 61.0, and artificial lift moves above 70 percent.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 5, 'The teaching well is at 74.5 percent water and artificial lift comes back consider, while the sweep row at 60.0 percent reads no. What decides that?', '["The flowing flag, which the module sets false once the water cut passes 70 percent and the column is heavy.", "A threshold at 70 percent water, and nothing about the mechanism, which artificial lift never reads.", "The channelling mechanism, which is the reading that makes a heavy column worth lifting rather than shutting off.", "The skin of 7.5, since a damaged well is the one that stops flowing first and therefore needs the lift soonest."]'::jsonb, 1, 'The gate is arithmetic on one field of the well row. Artificial lift comes back candidate only when flowing is false.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 6, 'The four published histories are screened at the default window. How does the reduce drawdown verdict move across them?', '["It is a candidate on the channelling history, where a path of its own is what choking the well back is meant to close, and no on the rest.", "It is a candidate wherever the water shutoff is blocked, so it picks up the coning, the displacement and the flat histories together.", "It is a candidate on the flat history, since with no derivative fit under the reading the cheapest recommendation is the defensible one.", "It is a candidate on the coning history and comes back no on the other three."]'::jsonb, 3, 'Coning is drawdown pulling water through the same rock as the oil, so the squeeze is blocked and reduce drawdown takes its place, at a derivative slope of -0.539955222.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 7, 'Recompletion comes back candidate on one of the four published histories and consider on the other three. Which one, and why?', '["The coning history, because a cone is answered by moving the perforations away from the contact.", "The displacement history, because there is nothing else left to do on a swept well that still has a rig cost to justify.", "The channelling history, because a path of its own is often a poor cement bond or perforations into the wrong interval.", "The flat history, because with no mechanism established the completion is the only thing left that can be inspected."]'::jsonb, 2, 'Recompletion is candidate on channelling or above a skin of 8, and consider otherwise. It addresses the cause rather than sealing the symptom.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 8, 'The published flat history has every derivative at 0.000000000, so its derivative fit returns ok false with n = 0. What does the screening do with it?', '["It blocks the water shutoff on a mechanism of displacement at confidence n/a, which was named without a slope being measured.", "It refuses to screen at all, since a diagnosis carrying no slope is not a diagnosis the screening will accept.", "It screens it as though no diagnosis had been handed in, so the block reason is the one that asks for more production history.", "It returns the water shutoff as unknown, the verdict the module uses when a field it needs was never filled in."]'::jsonb, 0, 'The mechanism is named off the derivative branch that fires when everything is flat, and the shutoff is blocked on a reading that failed.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 9, 'screenTreatments refuses a treatment in two different ways. What distinguishes them?', '["A blocked verdict is issued by the water cut gate and a no by the mechanism gate, which is why only one of them can be reversed.", "A blocked verdict sets a boolean and carries a block reason; a no leaves the boolean false and carries none.", "A blocked verdict sorts below unknown and no in the ranked list.", "A blocked verdict carries three reasons and a no carries one."]'::jsonb, 1, 'Blocked sorts above unknown and no in the fixed order, so a blocked treatment prints higher than one the screening simply declined.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 10, 'Reduce drawdown is refused on a channelling reading and the water shutoff is refused on a displacement reading. Why does only one of them come back blocked?', '["Because the shutoff is refused after the water cut gate and reduce drawdown before it.", "Because blocked is the deeper refusal of the two, and a squeeze on a swept reservoir is a worse idea than choking back a well with a path in it.", "Blocked is a branch written for the water shutoff alone, so reduce drawdown is refused as a no with the boolean left false.", "Because reduce drawdown carries a reason naming the evidence that would reverse it, and a refusal that can be reversed is never blocked."]'::jsonb, 2, 'Reduce drawdown is refused by the mechanism and still comes back no with the boolean false. Blocked is not a rank of severity.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 11, 'The shutoff is refused once at 29.0 percent water and once by a reading taken at a late fraction of 0.9. Which refusal could a change in the well ever reverse?', '["Both, since the water cut and the mechanism are properties of one well.", "Neither of them, since both refusals were issued by the screening rather than by the diagnosis it was handed.", "The one at a late fraction of 0.9, since a window chosen by an analyst is the input most easily corrected on a rerun.", "The one at 29.0 percent, since at 30.0 percent the same row returns candidate with 3 reasons."]'::jsonb, 3, 'A no is waiting on the well and a block is waiting on the reading: at 0.5 those same 38 samples give channelling and a candidate.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 12, 'Two block reasons are written in this module. What separates them?', '["The displacement one closes the question and the no diagnosis one names the two things that would reopen it, more production history or a production log.", "The displacement one carries the derivative slope and the no diagnosis one carries no numbers at all.", "The displacement one is issued after the water cut gate and the no diagnosis one before it.", "The displacement one is checked against a published expected block reason and the no diagnosis one is not."]'::jsonb, 0, 'One says no treatment on this well will change it. The other says the mechanism has not been established, which is the honest refusal here.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 13, 'A displacement block on the teaching well arrives with the reason that the water cut is 75 percent and the derivative is flat. The reading behind it was taken at a late fraction of 0.9. What is wrong with the word flat?', '["Nothing, since the derivative fit at that window fell below minR2 of 0.5 and no slope was returned to contradict it.", "The derivative slope on that reading is 1.254360095 at a fit quality of 0.995286721 as a fraction, which is a climb rather than a flat line.", "Nothing, since the word describes the ratio slope of 1.103149966 rather than the derivative slope beside it.", "The reading was taken at a fraction the module clamps, so the string describes a window the analyst never asked for."]'::jsonb, 1, 'The string is a fixed label pushed by the displacement branch. At a late fraction of 0.5 the same history takes the channelling branch and the string becomes climbing, at 1.442132492.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 14, 'Every reason string on the teaching well prints a water cut of 75 percent. What does the well row actually carry?', '["75 percent, since the row and the strings are filled from the same field and cannot disagree.", "74.5 percent, which the strings round because the gates themselves are stated to the nearest 5 percent.", "74.5 percent, which is the figure the artificial lift gate at 70 percent and the shutoff gate at 30.0 percent are applied to.", "74.5 percent, which the strings round because the block reason is issued before the water cut is read."]'::jsonb, 2, 'The strings round and the gates do not. A reader checking 75 percent against a gate at 70 percent is checking a rounded number against an exact one.'),
  ('intervention', 'intermediate', 'module', 'm04-the-water-gate', 15, 'What does a block reason carry from the diagnosis that produced it?', '["The mechanism id and the confidence that came with it.", "The derivative slope and the threshold it was compared against, which together are the argument the block rests on.", "The window start in days, the one dimensional number the diagnosis returns.", "None of it: no slope, no fit quality, no confidence, no window start and no sample count."]'::jsonb, 3, 'The diagnosis holds all five and none reaches the string, and nothing checks it either: no expected verdict and no expected block reason is published anywhere.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 1, 'A well at 1899 scf/stb against an expected 950 comes back no with 1 reason, and the same well at 1900 scf/stb comes back consider with 2. What decided it?', '["The gas mechanism, which turns from coning to channelling as the measured ratio passes twice the expectation.", "The count of reasons the branch can justify once the measured ratio is far enough above the expectation.", "A ratio to the expected value of exactly 2.000000000, which is the whole of the gas shutoff test.", "The absolute ratio, since 1900 scf/stb is where solution gas stops accounting for it."]'::jsonb, 2, 'One scf/stb is the difference between the two rows, and 1899 scf/stb sits at 1.998947368 of the expectation while 1900 sits at 2.000000000.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 2, 'At 5000 scf/stb against an expected 950, more than five times the expectation, what verdict does the gas shutoff carry?', '["consider, the same word the well gets at 1900 scf/stb, because consider is the ceiling on this branch.", "candidate, since a ratio of 5.263157895 is past every doubt the branch is written to raise.", "blocked, since a ratio that far above the expectation cannot be a completion problem the squeeze could seal.", "marginal, which is the verdict the module reserves for a gate cleared by more than it was written for."]'::jsonb, 0, 'Two values appear in that column and no others across the whole sweep, and the reason count moves once, from 1 to 2.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 3, 'The same well row is screened at a late fraction of 0.5, at 0.9 and with no diagnosis at all. What happens to the gas shutoff?', '["It follows the water shutoff, so it is a candidate on the channelling reading and refused on the other two.", "It comes back consider with 2 reasons every time, because the gas branch never touches the diagnosis.", "It comes back consider on the two readings and unknown with no diagnosis, since the branch needs a mechanism before it will argue.", "It comes back consider on the diagnosed rows and blocked with no diagnosis, since a squeeze with no mechanism established is blocked."]'::jsonb, 1, 'The measured and expected ratios are two fields on the well row. No gas history is read, no slope is fitted and no mechanism is established.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 4, 'A well at 900 scf/stb and a well at 1899 scf/stb, both against an expected 950, get what from the gas branch?', '["Different verdicts, since 900 scf/stb sits below the expectation at 0.947368421 and 1899 sits at 1.998947368, all but double it.", "The same verdict of no, but with a second reason on the higher of the two, naming how close the gate came to opening on it.", "Different reason counts, since the branch reports the ratio to expected only once that ratio has passed one.", "The same verdict of no, with 1 reason and the identical text."]'::jsonb, 3, 'The refusal bucket runs from 0.947368421 to 1.998947368 and is one word wide, so a ratio all but double the expectation reads the same as one below it.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 5, 'Five of the six gates in this screening test a number against a constant written into the module. Which is the sixth, and what does it test against?', '["The gas shutoff, which tests the measured ratio against an expected ratio the user typed on the well row.", "The water shutoff, which tests the water cut against the expectation carried alongside it on the same row.", "The matrix acid gate, which tests the skin against the minimum the geometry allows.", "The recompletion gate, which tests the mechanism against the confidence returned with it rather than against a threshold."]'::jsonb, 0, 'The water cut gates sit at 30.0 percent, between 60.0 and 61.0 percent and above 70 percent, and the acid gate at a skin above 2. Only the gas boundary is written by the user.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 6, 'What in the screening derives the expected gas-oil ratio?', '["The diagnosis, which returns it alongside the mechanism whenever it is run on a gas-oil ratio history.", "Nothing. No pressure is read anywhere, no solution gas-oil ratio is computed and no bubble point is consulted.", "The oil rate and the gas rate on the well row, whose quotient is the expectation the measured value is tested against.", "The published golden, which carries an expected gas-oil ratio for each of its four labelled histories."]'::jsonb, 1, 'It is a field on the well row like the water cut and the skin, and the pair reaches the reader only inside a reason string, never in a field to check.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 7, 'Why can a gas shutoff never come back better than consider?', '["Because a gas squeeze costs more than a water squeeze, so the module holds it one verdict lower throughout.", "Because the gas gate fires after the water cut gate, and a treatment gated twice cannot reach the top of the enumeration.", "The branch tested a ratio of two typed numbers and not a mechanism, and the second reason it carries says so.", "Because gas coning and gas channelling cannot be told apart by a log-log slope, so no gas verdict is ever more than arguable."]'::jsonb, 2, 'The ceiling is the branch admitting it has not finished: it asks for the diagnostic to be run on the gas-oil ratio before deciding.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 8, 'The gas branch ends by asking that the diagnostic be run on the gas-oil ratio. How would a later reader tell whether that was ever done?', '["In a field on the gas shutoff verdict, which stays set until a gas diagnosis is handed back to the screening.", "In the ranked order, which drops the gas shutoff below the treatments whose evidence is complete until the reading is done.", "In the reason count, which falls from 2 to 1 on the next screening once the second reading has actually been carried out.", "Only from the analyst writing it down, because nothing in the returned object marks the instruction as outstanding."]'::jsonb, 3, 'The verdict is identical whether the instruction was followed or ignored, so the only trace that the second reading was run is the analyst writing it down.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 9, 'How does the water side handle a caveat of the same kind?', '["It drops the verdict from candidate to consider, which is what the gas branch does with its own outstanding work.", "It puts it into the reason list of the treatment it is recommending, asking for a production log before committing to a squeeze.", "It sets the blocked boolean and writes the caveat into the block reason, so the refusal and its condition arrive together.", "It reports the confidence beside every verdict, so a reader can see which recommendations rest on a low confidence reading."]'::jsonb, 1, 'That caveat is read in exactly one place, on a channelling water shutoff returned as a candidate, and the gas instruction has no equivalent field anywhere.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 10, 'Why do the diagnosis thresholds transfer from a water-oil ratio to a gas-oil ratio in scf/stb without rescaling?', '["They are boundaries on a log-log slope, and a log-log slope carries no unit, so 1.3, 0.25 and -0.1 describe the shape of a climb rather than the size of a ratio.", "The engine normalises every ratio history by its first sample before fitting, so the thresholds see a dimensionless series either way.", "The gas-oil ratio is converted to a bare ratio inside the diagnosis, so the thresholds are applied to the same quantity in both cases.", "They do not transfer, which is why the gas branch stops at consider and hands the reading back to the analyst."]'::jsonb, 0, 'The same function reads either fluid. A slope of 1.3 is a rate of climb per log cycle and it is not a quantity of water or of gas.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 11, 'What transfers along with the instruction to read the gas history?', '["Nothing, since the gas reading is a fresh call and the fraction resets to a value chosen for the fluid being read.", "The water cut gate, which is applied to the gas reading as well and refuses it under 30.0 percent water.", "The window problem entire: a default of 0.5, a clamp to the range 0.1 to 1.0, and a derivative slope that moves by 0.370920348 across that dial.", "The expected ratio, which the diagnosis reads off the well row and uses as the baseline the slope is measured against."]'::jsonb, 2, 'The gas reading clears the same gates too: a minimum fit quality of 0.5 as a fraction, a minimum span of 0.4 log cycles, and six producing samples as the bare minimum.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 12, 'The second reading on the gas history comes back indeterminate. What has the analyst got?', '["A failed reading, which should be repeated at a window fraction that returns a mechanism the screening can act on.", "A verdict the screening will read as displacement, since indeterminate and displacement both leave the shutoff refused.", "Nothing usable, since the gas shutoff was already at consider and an indeterminate reading cannot move it any further.", "An answer: do not spend money on a treatment chosen by guesswork."]'::jsonb, 3, 'That is the note the mechanism carries, and it is the module refusing in a form that can be acted on rather than failing to reach a verdict.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 13, 'screenTreatments reads five fields off the well row and one off the diagnosis. Which of these does it never read?', '["The gas-oil ratio and the expected gas-oil ratio, which reach the screening only through the diagnosis.", "Any oil, water or gas rate, any pressure or drawdown, the permeability, and the drainage and wellbore radii.", "The flowing flag, which the artificial lift branch infers from the water cut rather than reading directly.", "The skin, which the module reads out of the multiplier it computes rather than off the well row."]'::jsonb, 1, 'It reads the water cut, the skin, the two gas-oil ratios, the flowing flag and the mechanism id, and nothing else about the well.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 14, 'The module can compute what removing skin is worth, and on the teaching geometry a designed acid job returns a multiplier of 2.879215612184. What does the screening do with that?', '["Nothing. It never calls the multiplier, and matrix acid is gated on the skin alone: candidate above 2, marginal above 0, no at or below 0.", "It ranks matrix acid above the other candidates, since the multiplier is the only number in the module that prices a treatment.", "It returns the multiplier alongside the matrix acid verdict, which is why that verdict carries a reason quoting the skin of 7.5 as heavy damage.", "It uses it to break the tie between the three candidate verdicts, which is the one place a number enters the ranking."]'::jsonb, 0, 'No verdict in the seven carries a cost, a volume, a duration or a rate, and with no skin entered matrix acid comes back unknown rather than refused.'),
  ('intervention', 'intermediate', 'module', 'm05-the-gas-side', 15, 'A verdict issued off a 19 sample late window and one issued off a 35 sample window are compared. What does the screening output show of the difference?', '["The reason count, which falls as the window widens and the reading loses confidence.", "The blocked boolean, which is set on the wider reading because a window that wide is refused by the span gate.", "Nothing at all, since it takes the mechanism id and leaves the two fit qualities and the window start behind.", "The window start in days, which is copied into the first reason on every treatment the diagnosis gated."]'::jsonb, 2, 'The diagnosis it was handed holds a ratio fit quality of 0.921895186, a derivative fit quality of 0.998513658 and a window start of 250.242976 days, and none of them is read.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The working order puts a fit of the raw unwindowed history before any window is chosen. What is that step for?', '["It establishes the mechanism early, so a window that changes the mechanism afterwards can be recognised as the wrong window.", "It is where the count the fit returns can be set against the samples handed in, since points that are not strictly positive are dropped without a word.", "It fixes the span the later reading is measured against, since a windowed span is only meaningful beside the span of the whole history.", "It clears the six sample minimum before a fraction is applied, which is the one gate that counts rather than measures."]'::jsonb, 1, 'logLogSlope fits what survives the drop and reports the count after it, so the only way to see a drop happened is to compare that count with what was handed in.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Working a history in order, what should be written down at the window step?', '["The fraction that was used and the window start in days, because the fraction is in no field of the result and the start is the only trace of it.", "The fraction alone, since the window start is recomputed from it whenever the reading is repeated.", "The span in log cycles, since it is the field named for the reading and therefore the one a reader will look for.", "The mechanism and its confidence, since a window is defensible once the verdict it produced is stable."]'::jsonb, 0, 'The clamp to the range 0.1 to 1.0 names nothing when it fires, so identical starts across different typed fractions are its only signature.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Both slopes come back from one call. What has to be recorded beside each of them?', '["The threshold each was compared against, since the two are tested against different boundaries.", "The fit quality of the other one, since the pair is only interpretable as a difference between them.", "The count of samples each was fitted on, because the ratio slope uses every late sample and the derivative slope only the ones climbing.", "The intercept of each, since a slope without its intercept does not reconstruct the line it came from."]'::jsonb, 2, 'On the teaching well at the default that is 19 samples against 15, and the object carries one span, 0.900620470, which belongs to the shorter fit.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Which two gates does the working order check before a mechanism is read off the slopes?', '["A minimum fit quality of 0.5 as a fraction and a minimum window of 0.4 log cycles measured across the samples selected.", "A minimum ratio of 0.1 on the last sample and a minimum window start late enough to sit in boundary-dominated flow.", "A minimum of six producing samples and a maximum window fraction of 1.0, which are the two the module enforces itself.", "A minimum fit quality of 0.5 as a fraction and a minimum span of 0.4 log cycles."]'::jsonb, 3, 'The span gate is applied to the span the derivative fit reports rather than to the window that was selected, which is why the two are recorded separately.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'The order says to record the margin against 1.3 as a signed number rather than as a mechanism. Why?', '["Because the sign and the size are the whole argument: at the default window the teaching well clears the boundary by 0.142132492 and the dial is worth 0.370920348.", "Because the mechanism is a string and a report cannot be audited from strings.", "Because the sign tells a reader which of the two thresholds, -0.1 or 1.3, the reading was compared against.", "Because the margin is the quantity the ambiguous flag is computed from, so recording it reproduces the flag."]'::jsonb, 0, 'A margin smaller than the range of an untyped analyst choice is the sentence a reader needs, and the mechanism alone does not carry it.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The order says to read the ambiguous flag and the confidence out of the object rather than to infer them. What is the reason?', '["They are the only two fields in the whole object that an independent oracle has ever checked, so quoting them straight out of the result is the one way to quote a verified value.", "They are assigned by the engine''s own comparison, and a reader who recomputes them from the margin has substituted a second reading for the one that was made.", "They are computed from the two fit qualities rather than from the slope at all, so a margin worked out by hand against the boundary cannot reproduce either of them.", "They are absent whenever the derivative fit fails, so reading them is the way to tell a failed fit from a successful one."]'::jsonb, 1, 'The band runs from 1.050000 to 1.550000 on the derivative slope, and what the object says about a reading is the record of what the module actually did.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'What does the order require at every call into the geometry functions?', '["A comparison of the after-skin against the achievable range of about -3 to -5 on acid, since that is the check the module performs before it hands back a multiplier.", "A repeat of the call at a second drainage radius, since the group is a logarithm and a guessed radius has to be bracketed.", "A finite check on the result, because pssDenominator, minimumSkin and skinFromPiRatio return a bare NaN where skinPiMultiplier returns an ok flag.", "The ok flag read first, since every function in this group returns an object carrying one."]'::jsonb, 2, 'Two failure contracts sit in one module, so code that checks the ok flag and forgets the finite check reads a refusal as a number.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'What is the single dimensional number a diagnosis returns?', '["The span, which is a length of producing history expressed in log cycles rather than in days.", "The ratio slope, which carries the unit of the ratio column it was fitted on.", "The last sample ratio, which is the value the minimum ratio gate of 0.1 is applied to.", "The window start in days."]'::jsonb, 3, 'Everything else it hands back is a slope, an intercept, a fit quality or a span, and a log-log slope carries no unit at all.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'A diagnosis returns a mechanism, two slopes, two fit qualities, a span, a start time and a confidence. What is under all of it?', '["No reservoir model at all: the ratio history and the derivative column beside it are inputs, and nothing in the module computes either one.", "A material balance on the swept volume, which is the calculation that separates a reservoir arriving at the well from water that has found a path of its own.", "A radial Darcy rate in SI, which is the route the oracle uses and the module inherits from it.", "A pseudo-steady-state productivity index built on a circular drainage area, which is where the 3/4 in the geometry group comes from and what the ratio history is read against."]'::jsonb, 0, 'It sizes nothing either: no cost, no volume, no duration, no rate and no pressure appears anywhere in the return.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What is the limit that survives everything else in this course?', '["A Chan reading cannot be taken on a gas-oil ratio in scf/stb, because the thresholds were set on water-oil ratios carried as a bare ratio and would have to be rescaled first.", "For any power-law history the ratio and its derivative carry the same log-log slope, so only steepness separates displacement from channelling.", "A diagnosis is only ever as good as the fit quality under it, and below the minimum of 0.5 as a fraction the reading is refused as scatter rather than reported as a slope.", "A verdict cannot be reached on fewer than six producing samples, which is the bare minimum the module states."]'::jsonb, 1, 'The engine says so in its own note, and it is why a channelling boundary of 1.3 and a band of 0.25 are choices about where to cut rather than measurements.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Which numbers in the chain has an independent route ever confirmed?', '["The mechanism and the confidence, which the four published histories carry beside their late derivative slopes.", "The window start in days, which the oracle reproduces on all four published histories at its own series[20:] boundary.", "The log-log slope, by the median of every pairwise slope, and the skin multiplier, by a radial Darcy rate built in SI.", "The seven screening verdicts, which the published file carries for the four labelled histories it publishes."]'::jsonb, 2, 'chanDiagnosis, screenTreatments, rankTreatments and skinFromPiRatio are asserted against nothing, so every verdict produced is a reading carrying the engine''s name.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Which single field of a diagnosis, quoted on its own, would let a colleague reproduce the verdict?', '["The derivative slope, since the mechanism follows from that one number alone and from the two fixed thresholds it is compared against.", "The window start in days, since the fraction can be recovered from it once the sample times are known.", "spanDecades, since it fixes both the length of the reading and the samples that went into it.", "None of them, because a mechanism is a slope read over a window and the object records the window only as a start time."]'::jsonb, 3, 'The fraction appears in no field, and the derivative slope alone does not say which of the samples it was fitted on or how many survived the filter.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Where in this working order does the screening sit?', '["First, because the water cut gate fires before any mechanism is read at all and can refuse the water shutoff squeeze on a well row alone, with no diagnosis handed in beside it.", "Last, after the reading and after the alternative has been priced, with the verdict, the blocked flag, the reason count and the block reason recorded for each treatment.", "Alongside the diagnosis, since the two calls are handed to each other and neither of them is complete on its own, the screening naming what the reading was taken for.", "Between the window and the slopes, because the screening is what decides which of the two slopes in the return the reading should properly be taken from on this well."]'::jsonb, 1, 'It reads one field off the diagnosis, the mechanism id, and it is the last step because everything it says rests on a reading already recorded.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'On the teaching geometry an acid job from a skin of 7.5 down to -2.2 is worth a multiplier of 2.879215612184. What has to be quoted beside it?', '["The water cut of 74.5 percent, since the screening reads it before it reads the skin.", "The rate the well would make once the job is placed, since a multiplier with no rate beside it is not a number a planner can put into a recommendation and act on.", "The geometry floor of -7.361728083308, since the guard the multiplier cleared is the pole and not a statement about what a treatment can reach.", "The confidence returned with the diagnosis, since the acid job is the alternative to the water treatment that same reading recommended and inherits its caveat."]'::jsonb, 2, 'The multiplier is a ratio of two productivity indices at the same drawdown, and the floor is the only limit the function actually enforces.'),
  ('intervention', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'A write-up is arithmetically right at every line and its recommendation is still wrong. Which choice would explain that?', '["Choosing the window, because every slope, fit quality, span and verdict after it is computed correctly on whatever window was set.", "Screening the well, because a verdict issued before the diagnosis is read has no mechanism id behind it.", "Pricing the alternative, because a multiplier computed before the skin is confirmed carries the wrong before-skin into every later figure.", "Counting the samples, because a history under six samples is refused outright and nothing downstream of it runs at all."]'::jsonb, 0, 'The dial moves the derivative slope by 0.370920348 while the margin deciding the spend is 0.142132492322, and nothing later in the order can recover the choice.'),
  ('intervention', 'intermediate', 'final', null, 1, 'A planner is handed two recommendations on one well, one recommending a squeeze and one refusing it, and the 38 samples behind them are identical. What is the smallest thing that could have differed?', '["The water cut on the well row, since the shutoff opens at 30.0 percent and refuses below it whatever the history says.", "The skin entered beside the history, since the matrix acid gate at a skin above 2 also moves the shutoff.", "The late fraction typed into the reading, 0.5 against 0.9, which moves the derivative slope from 1.442132492 to 1.254360095 across the boundary of 1.3.", "The confidence, since the shutoff is refused whenever the reading it rests on comes back low rather than high."]'::jsonb, 2, 'One untyped analyst choice turns the shutoff from a candidate with 3 reasons into a block with 1, and no field in either result records the choice.'),
  ('intervention', 'intermediate', 'final', null, 2, 'A reading comes back channelling at low confidence and the water shutoff is a candidate. Where does the low confidence appear downstream?', '["In the third reason on that candidate, asking for a production log before committing to a squeeze, and nowhere else in the seven verdicts.", "In the blocked boolean on that treatment, which is left false precisely because the reading behind it was not confident enough to block anything.", "In the ranked order, which drops a low confidence candidate below the treatments gated only on the well row.", "In every reason string the screening produces on that well, since the caveat belongs to the diagnosis as a whole rather than to any one treatment."]'::jsonb, 0, 'The displacement and coning branches block without reading the confidence or the ambiguous flag at all, so the caveat rides on the verdict that spends money.'),
  ('intervention', 'intermediate', 'final', null, 3, 'A user types a late fraction of 0.05 on the teaching well and screens the result. What does the screening return for the shutoff and for reduce drawdown?', '["The shutoff a candidate and reduce drawdown no, since the clamp leaves the default channelling reading in place.", "The shutoff blocked and reduce drawdown no, since a reading with no derivative slope in it names no mechanism to act on.", "Both unknown, since a fraction the module will not use leaves the mechanism id unset on the diagnosis it hands over.", "The shutoff blocked and reduce drawdown a candidate, because the clamped reading came back coning."]'::jsonb, 3, 'The floor of 0.10 opens the window at 2308.407093 days where no positive derivative survives, and coning is not treatable, so the spend is decided by a typed value that was discarded.'),
  ('intervention', 'intermediate', 'final', null, 4, 'The published flat history reaches a screening verdict without a slope ever being fitted. Trace how.', '["The ratio slope of 0.000000000 is compared against the channelling boundary of 1.3 in place of the missing derivative slope, and a displacement verdict follows.", "Every derivative is 0.000000000, so the fit returns ok false with n = 0, the flat branch names displacement, and the shutoff is blocked on that name.", "The mechanism is carried over from the published metadata, which gives a late derivative slope of null and therefore no climb to read.", "The screening reads the ratio fit quality of 0.000000000 and blocks the shutoff on the grounds that the reading it was handed failed its own quality gate."]'::jsonb, 1, 'A mechanism was named on a fit that returned nothing, and the verdict that followed cannot be distinguished in the output from one read off 20 clean samples.'),
  ('intervention', 'intermediate', 'final', null, 5, 'The module can compute what a stimulation is worth and the screening gates the same treatment. How do the two meet?', '["The multiplier sets the verdict, so a job worth more than double comes back candidate and one worth less comes back marginal.", "The multiplier is quoted inside the matrix acid reason string, which is how a planner sees the value of the job.", "They do not. Matrix acid is gated on the skin alone, candidate above 2, and the multiplier of 2.879215612184 on that same designed job is never called.", "The multiplier breaks the tie between the three candidate verdicts, which is the one place a computed number enters the ranking."]'::jsonb, 2, 'No verdict in the seven carries a cost, a volume, a duration or a rate, so the screening establishes that a treatment is arguable and prices nothing.'),
  ('intervention', 'intermediate', 'final', null, 6, 'The gas branch asks for the diagnostic to be run on the gas-oil ratio. What does the second reading inherit?', '["Every property of the first: a default fraction of 0.5, a silent clamp, and a derivative slope that moves by 0.370920348 across the dial.", "A rescaled set of thresholds, since a ratio in scf/stb has to be normalised before 1.3 can be applied to it.", "A window fixed by the first reading, so that the water and the gas are read over the same stretch of history.", "A relaxed span gate, since a gas history is usually shorter than the water history recorded beside it."]'::jsonb, 0, 'The same function reads either fluid and its thresholds are log-log slopes carrying no unit, so the window problem arrives with them intact.'),
  ('intervention', 'intermediate', 'final', null, 7, 'At a late fraction of 0.20 the window runs 0.450310235 log cycles, comfortably past minSpanDecades of 0.4, and the reading still comes back indeterminate with no span. Why?', '["The window holds 8 samples, below the six the module requires before it will fit anything at all.", "The fit quality at that window is 0.999944740, which the classifier reads as too clean to be a real measurement.", "The clamp replaced 0.20 with the floor of 0.10, and the floor window is too short to carry a fit.", "The gate is applied to the span the derivative fit reports after the falling samples are dropped, not to the window."]'::jsonb, 3, 'Dropping the contrary samples costs 0.257320134 of a log cycle, so a reader who checks the window against 0.4 passes a window the fit then fails.'),
  ('intervention', 'intermediate', 'final', null, 8, 'A vendor claims a 6.000 times uplift and a reading calls the well channelling. Which of those two numbers has an independent route behind it?', '["The uplift, since the skin multiplier is checked by a radial Darcy rate in SI, and that check covers the inverse as well.", "Neither. skinFromPiRatio and chanDiagnosis are both asserted against nothing at all.", "The mechanism, since the published histories carry a late derivative slope the classifier reproduces before it names anything.", "Both, since the log-log slope and the skin group are the two functions the oracle checks and every verdict is built on them."]'::jsonb, 1, 'The two routes are on logLogSlope and skinPiMultiplier. The inverse and the classifier ride on checked arithmetic and are themselves checked by nothing.'),
  ('intervention', 'intermediate', 'final', null, 9, 'A block reason on the teaching well reads that the water cut is 75 percent and the derivative is flat. What was the derivative actually doing?', '["Falling, which is why the reading was blocked, and flat is the branch''s own word for a falling derivative.", "Sitting at 0.000000000 across the late window, which is exactly what the word describes on that reading.", "Climbing at 1.254360095 at a fit quality of 0.995286721 as a fraction, on the reading taken at a late fraction of 0.9.", "Climbing at 1.442132492, which is the reading the block was issued on before the window was widened."]'::jsonb, 2, 'The word is a fixed label pushed by the displacement branch, and displacement is the roughly proportional climb rather than a flat line.'),
  ('intervention', 'intermediate', 'final', null, 10, 'Two boundaries decide two squeezes on one well. Who chose each of them?', '["The module chose the water cut gate at 30.0 percent, and the user chose the gas boundary by typing an expected gas-oil ratio.", "The module chose both, at 30.0 percent water and at 1900 scf/stb of measured gas.", "The user chose both, since the water cut and the measured gas-oil ratio are fields on the well row.", "The module chose both, and the gas boundary moves only when the diagnosis on the gas history returns a different mechanism."]'::jsonb, 0, 'The gas gate is a factor of two on whatever expectation was entered, so the same measured gas can sit on either side of it.'),
  ('intervention', 'intermediate', 'final', null, 11, 'A recommendation quotes a block reason in full as its evidence. What has been left out?', '["The mechanism id, which the block reason names only by implication and never in the words the module uses for it.", "The verdict order, without which a reader cannot tell whether the treatment was blocked or simply declined by a no.", "The water cut, which the block reason omits although the reason line beside it carries the figure.", "The slope, the fit quality, the confidence, the window start and the sample count, none of which reaches the string."]'::jsonb, 3, 'The diagnosis holds all five. A block reason is the branch restating itself, identical on every well that reaches it.'),
  ('intervention', 'intermediate', 'final', null, 12, 'A reading is written up as channelling with a note that it was flagged ambiguous. What does the working order say to record with it?', '["The ambiguous band alone, since 0.25 is the number that produced the flag and the slope adds nothing to it.", "The margin against 1.3 as a signed number, since 0.142132492 sits inside a band of 0.25 and the sign is half the argument.", "The confidence, since a flagged reading is always low and the two fields say the same thing twice.", "The mechanism note in full, since it is the only place the module explains why the boundary is weak."]'::jsonb, 1, 'Confidence and the flag come out of the object rather than out of a reader''s own comparison, and the margin is what makes the flag reproducible.'),
  ('intervention', 'intermediate', 'final', null, 13, 'A slope of 1.442132492 is reported with no window beside it. What can a reader not do with it?', '["Compare it against the channelling boundary of 1.3, which requires the span the fit sat on.", "Tell whether it is a ratio slope or a derivative slope, since neither carries a unit to distinguish them.", "Reproduce the verdict, since the same history read whole gives 1.229355999 and a different mechanism.", "Check it against the published late derivative slope of 1.600000000000 for a channelling history."]'::jsonb, 2, 'A slope without its window is not a measurement of the well: two careful analysts hand in two numbers from one series and the module answers them differently.'),
  ('intervention', 'intermediate', 'final', null, 14, 'What is the only trace in a result that a window fraction was silently replaced?', '["The start time in days, since every fraction at or below 0.10 reports 2308.407093 on one teaching history and every fraction at or above 1.00 reports 15.000000.", "A note appended to the reading, which names the value used whenever it differs from the one handed in.", "The confidence, which is dropped to low on any reading computed from a substituted input.", "The span, which shortens whenever the floor is applied and lengthens whenever the ceiling is."]'::jsonb, 0, 'The clamp to the range 0.1 to 1.0 is documented nowhere: not in the object, not in a note and not in a warning.'),
  ('intervention', 'intermediate', 'final', null, 15, 'Why do two wells with the same producing life get different late windows from one fraction?', '["The fraction is applied to the span in log cycles, so a well with a longer early history keeps more of it.", "The fraction is applied to the number of samples, so a well reported more often opens its window later in time.", "The fraction is applied to producing time, and the two wells differ in how much of that time they were shut in for.", "The fraction is applied to the samples with a positive derivative, and the two wells differ in how many they have."]'::jsonb, 1, 'The window opens at whichever sample the count lands on, and the object records it only as a start time in days.'),
  ('intervention', 'intermediate', 'final', null, 16, 'A history at a late fraction of 0.80 returns 1.292632524 and one at 0.70 returns 1.336892539. What lies between those two verdicts?', '["A change in the fit quality, from 0.995879922 to 0.996676450, across the minimum of 0.5.", "A change in the reported span, from 1.672580873 to 1.415260738 log cycles, across a minimum of 0.4.", "A change in the count of late samples, from 31 to 27, across the six sample minimum the module enforces.", "A margin of 0.007367476 against a boundary of 1.3."]'::jsonb, 3, 'That margin on a log-log slope is far under what a production allocation could resolve, and the shutoff turns from candidate to blocked across it.'),
  ('intervention', 'intermediate', 'final', null, 17, 'A five sample history is handed to the diagnosis. What comes back?', '["ok true with the mechanism indeterminate, since a history that short is a reading which does not settle the question either way.", "ok true with the whole history taken as the late window, since a fraction of five samples cannot be split.", "ok false, mechanism indeterminate, every slope n/a, and the words that six producing samples is the bare minimum.", "A bare NaN, which is the failure contract the diagnosis shares with the geometry functions."]'::jsonb, 2, 'It is the one gate in the module that counts before it reads, and it is the only input the diagnosis refuses outright.'),
  ('intervention', 'intermediate', 'final', null, 18, 'One object carries worSlope, worR2, derivativeSlope, derivativeR2 and spanDecades. How many distinct sets of samples produced those five numbers?', '["One, since every field in the object is computed from the late window the fraction selected.", "Two, since the ratio pair is fitted over every late sample and the derivative pair over the climbing ones only.", "Three, since the span is measured over the selected window while each of the two fits is measured over samples of its own.", "Two, since the ratio pair is fitted over the whole history and the derivative pair over the late window."]'::jsonb, 1, 'On the teaching well at the default that is 19 samples against 15, and spanDecades belongs to the second of them at 0.900620470.'),
  ('intervention', 'intermediate', 'final', null, 19, 'Which single number in a diagnosis is compared against a threshold?', '["The derivative slope, against a coning boundary of -0.1 and a channelling boundary of 1.3.", "The ratio slope, against the same two boundaries, with the derivative used to break a tie between them.", "The derivative fit quality, against the minimum of 0.5, which is what separates the four mechanisms.", "The larger of the two slopes, since a mechanism is read off whichever line climbs more steeply."]'::jsonb, 0, 'The ratio slope sits in the same object and is never consulted: on the published coning history it reads 0.230022389 and still climbing.'),
  ('intervention', 'intermediate', 'final', null, 20, 'Two readings both fit their data at a quality of 1.000000000. One is flagged ambiguous and one is not. What is the flag reporting?', '["How much scatter the derivative carried, which is what a fit quality of 1.000000000 conceals on a short window.", "How far the ratio slope and the derivative slope stand apart, which is the disagreement the flag exists to mark.", "How many samples survived the positive filter, since a flag is raised whenever too few of them are left to trust.", "How near the slope landed to 1.3, and nothing else."]'::jsonb, 3, 'A slope of 1.150000000 sits inside a band running from 1.050000 to 1.550000 and a slope of 1.000000000 sits below it.'),
  ('intervention', 'intermediate', 'final', null, 21, 'A derivative slope lands just under the coning boundary of -0.1. What does the reading carry?', '["A coning verdict flagged ambiguous, since the band is applied around whichever boundary was crossed.", "An indeterminate verdict, since a slope that close to a boundary does not settle the question.", "A coning verdict with no ambiguity reported, because the band is applied at 1.3 and never at -0.1.", "A coning verdict at low confidence, since confidence falls whenever a slope lands within 0.25 of any threshold."]'::jsonb, 2, 'The band exists on the boundary that recommends the spend and not on the one that refuses it, and coning blocks the squeeze.'),
  ('intervention', 'intermediate', 'final', null, 22, 'A reading at a derivative fit quality of 0.999944740 is called low confidence and one at 0.948751314445 is called high. What has been confused if a report calls the second the better reading?', '["Nothing, since the published history is the one an independent oracle has checked and the teaching row is not.", "Confidence with fit quality: the word records where a slope landed against a threshold, not how well the line fitted.", "The fraction with the percentage, since 0.948751314445 as a percentage is the larger of the two numbers.", "The ratio fit with the derivative fit, since the confidence is assigned on the ratio and the quality quoted on the derivative."]'::jsonb, 1, 'The best fit in the group earns the worse label, because the label is the ambiguous flag under another name.'),
  ('intervention', 'intermediate', 'final', null, 23, 'A derivative fit falls below the minimum fit quality. In what terms does the module say so?', '["As a percentage, on the words that the fit explains only 0.0 percent of it, while the same quantity is a fraction in the object.", "As a fraction, quoting the minimum of 0.5 that the fit failed to reach on the late window.", "As a count, naming how many of the late samples were still left once the positive derivative filter had run over the window and dropped the rest.", "As a span, since a fit too poor to carry a slope is reported back as a span shorter than the minimum of 0.4 log cycles the module asks for."]'::jsonb, 0, 'Fit quality is a fraction in this engine and a percentage in its own error messages, which is why every quotation of it has to say which.'),
  ('intervention', 'intermediate', 'final', null, 24, 'A climbing water-oil ratio history reaching 20.279117393 ends with a post shut-in test of 0.060000000. What does the diagnosis return?', '["Channelling, since the climb across the rest of the history is what the late window is fitted on.", "Indeterminate, since one sample lying far below the established trend leaves the history unable to settle the question.", "Displacement at low confidence, with the slope of 1.150000000 the restored history returns.", "Displacement with no slope, no span and no confidence, on the note that the ratio is still only 0.060."]'::jsonb, 3, 'The minimum ratio of 0.1 is compared against the last sample alone, so one bad meter or one test after a shut-in short-circuits the whole reading.'),
  ('intervention', 'intermediate', 'final', null, 25, 'What does the pseudo-steady-state group consist of?', '["The drainage radius over the wellbore radius, less 3/4, times the skin, all in consistent field units.", "The natural logarithm of the drainage radius over the wellbore radius, less 3/4, plus the skin.", "The natural logarithm of the drainage radius over the wellbore radius, plus 3/4, times the flow efficiency.", "The flow efficiency against an undamaged well, less 3/4, plus the skin the well is carrying today."]'::jsonb, 1, 'Productivity is inversely proportional to it, so on the published geometry it reads 7.900724584041 at zero skin and the uplift is one such group over another.'),
  ('intervention', 'intermediate', 'final', null, 26, 'Removing one unit of skin is worth 12.657067 percent on a well at a skin of 1.0 and 3.717372 percent on one at 20.0. Which well would you treat first if the rig cost the same?', '["The damaged one, because a whole job on it removes many units, even though each unit is worth less than on the clean well.", "The clean one, since the sweep shows each unit of skin removed there is worth more than three times as much.", "Neither, since the multiplier is a ratio of two dimensionless groups and does not compare two different wells.", "The damaged one, since the flow efficiency of 0.496878274 at a skin of 8.000 is the figure any uplift on it is measured against."]'::jsonb, 0, 'A stimulation on a lightly damaged well buys the most per unit and one on a badly damaged well buys the most in total.'),
  ('intervention', 'intermediate', 'final', null, 27, 'An after-skin of -6.800 on the teaching geometry returns 26.457156986. What does the module say about it?', '["It returns the multiplier with a warning quoting the achievable range of about -5 to -6 on a fracture.", "It refuses, on the grounds that the design is past everything the module calls real for a fracture.", "It returns the multiplier and the geometry floor of -7.361728083 with the two compared in a note.", "Nothing at all: warnings none, notes none, and an ok flag of true."]'::jsonb, 3, 'The guard fires only where the denominator reaches zero, so 26.457156986 arrives with the same confidence as 6.292734624 at an after-skin of -5.000.'),
  ('intervention', 'intermediate', 'final', null, 28, 'Some functions in this module report a bad geometry with an ok flag and an error string, and some with a bare NaN. Which do which?', '["skinPiMultiplier and skinFromPiRatio return the object; pssDenominator and minimumSkin return the bare NaN.", "All four return the object with its flag, and a bare NaN comes back only from the diagnosis when the history handed in is too short.", "skinPiMultiplier returns the object with the flag; pssDenominator, minimumSkin and skinFromPiRatio return the bare NaN.", "All four return a bare NaN for a bad geometry, and the ok flag belongs to the diagnosis rather than to any of the geometry functions."]'::jsonb, 2, 'Two failure contracts in one module means a caller that reads the flag and skips the finite check cannot tell a refusal from an answer.'),
  ('intervention', 'intermediate', 'final', null, 29, 'A fold increase quoted by a vendor converts to a post-job skin of -6.134773403 on the teaching geometry. Which sentence in the module is that figure to be set beside?', '["The geometry floor of -7.361728083, which the implied skin is still comfortably above.", "The module''s own sentence that a fracture reaches about -5 to -6, which the implied skin has already passed.", "The five published skin pairs, whose largest multiplier of 4.060771880315 the claim comfortably exceeds on a geometry of its own.", "The round trip on the published pairs, which recovers the stated skin after treatment to within 8.8818e-16 of the value published for it."]'::jsonb, 1, 'Auditing the fold increase makes a large but ordinary sounding claim; auditing the skin makes it a claim to have beaten the best fracture the module admits to.'),
  ('intervention', 'intermediate', 'final', null, 30, 'The water cut is walked from 10.0 percent to 90.0 percent with the diagnosis held fixed. Where does the shutoff first become a candidate?', '["At 61.0 percent, where the fracture picks up its third reason and the water becomes the argument.", "Above 70 percent, where artificial lift also turns from no into consider on the same row.", "At 74.5 percent, which is the water cut the teaching well row carries and the point the sweep is built around.", "At 30.0 percent, where its reason count goes from 1 to 3."]'::jsonb, 3, 'The gate fires before the mechanism is read, so a channelling reading buys nothing at 29.0 percent water.'),
  ('intervention', 'intermediate', 'final', null, 31, 'What separates a treatment returned blocked from one returned no?', '["Blocked is issued by the mechanism and a no by the water cut gate, which is why only a blocked verdict can ever be argued with on the evidence.", "Blocked carries three reasons and no carries one, which is the difference a reader sees in the output.", "Blocked sets a boolean and carries a block reason; a no sets nothing and carries none, and blocked sorts higher in the ranked list.", "Blocked is checked against a published expected verdict and a no is not, since the golden asserts the refusals and leaves the rest alone."]'::jsonb, 2, 'In every screening this course prints, the only treatment that ever comes back blocked is the water shutoff squeeze.'),
  ('intervention', 'intermediate', 'final', null, 32, 'What does the position of a treatment in the ranked list tell a planner?', '["That it is worth more than the ones below it, since the ranking is built from the uplift each treatment would buy.", "That its verdict sorts earlier in a fixed six-value order, and where two share a verdict, that it was pushed first in the source.", "That the diagnosis supports it more strongly than the rest, since the ranking is built from the mechanism and the confidence together.", "That it cleared more gates than the ones below it, since each gate a treatment clears moves it one place up the list."]'::jsonb, 1, 'Three treatments come back candidate at once on the teaching well, and nothing about the well breaks that tie.'),
  ('intervention', 'intermediate', 'final', null, 33, 'Two block reasons exist in this module. Which is the honest refusal, and why?', '["The one issued with no diagnosis, because it names the two things that would reopen the question, more production history or a production log.", "The displacement one, because it states a physical fact about a swept reservoir rather than reporting an absence of evidence to the reader.", "The displacement one, because it is the only block reason in the module attached to a mechanism the classifier actually went on to name.", "Neither, because a block reason carries no numbers and cannot be defended in either form."]'::jsonb, 0, 'The displacement block closes the question with the sentence that no treatment on this well will change it.'),
  ('intervention', 'intermediate', 'final', null, 34, 'A well makes 1899 scf/stb against an expected 950 and its neighbour makes 1900 against the same expectation. What is different in the screening output?', '["Nothing, since both sit under the factor of two and the gate has not opened on either.", "One verdict of consider against one of candidate, since the second of them clears the gate that the first only manages to reach.", "One verdict of no with 1 reason against one of consider with 2, on a ratio to expected of 1.998947368 against 2.000000000.", "One reason count of 2 against one of 3, since the second of them picks up the instruction to go and read the gas history."]'::jsonb, 2, 'One scf/stb decides it, and the gate is a factor of two on the expectation and nothing else.'),
  ('intervention', 'intermediate', 'final', null, 35, 'What is the best verdict a gas shutoff can reach, and why can it not do better?', '["candidate, which it reaches once the measured ratio passes twice the expectation and the gas history has been read.", "consider, because a gas squeeze is a rig job and the module never makes a rig job a candidate on arithmetic alone.", "marginal, because a gate cleared on an expectation the user typed cannot support a stronger word than that.", "consider, because the branch tested a ratio of two typed numbers rather than a mechanism."]'::jsonb, 3, 'At 5000 scf/stb against an expected 950 the answer is still consider, the same word the well gets at 1900 scf/stb.'),
  ('intervention', 'intermediate', 'final', null, 36, 'What does the screening never look at?', '["The skin, which it takes from the multiplier rather than from the well row.", "Any rate, any pressure, the permeability and the two radii, none of which appears among the fields it reads.", "The mechanism id, which reaches it only through the block reason attached to a refused treatment.", "The expected gas-oil ratio, which it derives from a bubble point and a pressure rather than reading it off the well row."]'::jsonb, 1, 'It reads the water cut, the skin, the two gas-oil ratios, the flowing flag and the mechanism id, and it prices nothing.'),
  ('intervention', 'intermediate', 'final', null, 37, 'Why is the whole raw history fitted before a window is chosen at all?', '["Because the fit silently drops every point that is not strictly positive, so the count it returns is the only way to see that a drop happened.", "Because the whole-history slope is the value the late reading has to be reconciled against before either of them can be quoted anywhere.", "Because the span of the whole history is what the minimum of 0.4 log cycles is applied to.", "Because a mechanism read on the whole history is the default the module falls back on whenever the window it was given is refused."]'::jsonb, 0, 'The count is reported after the drop and nothing says a drop occurred, so the comparison against the samples handed in is the check.'),
  ('intervention', 'intermediate', 'final', null, 38, 'A call into the geometry functions returns a number. What has to happen before it is used?', '["A comparison against the achievable range, since the module performs that check only on the refusal path.", "A repeat of the call at the published geometry, so that the teaching answer can be set against a published one before it is used.", "A finite check, since three of those functions signal a refusal by returning a bare NaN with no flag and no text.", "A conversion into field units, since the geometry functions work internally in SI and return in SI."]'::jsonb, 2, 'skinPiMultiplier is the one that returns an ok flag, and code written around that flag reads the other three refusals as answers.'),
  ('intervention', 'intermediate', 'final', null, 39, 'Which number does a diagnosis return that carries a physical unit?', '["The span of the derivative fit, which is a length of producing history in log cycles.", "The derivative slope, which is a rate of climb per log cycle and carries that unit.", "The ratio fit quality, which is a fraction of the variance in the ratio column it was fitted on.", "The start of the late window, in days."]'::jsonb, 3, 'This engine sizes nothing: no cost, no volume, no duration, no rate and no pressure appears anywhere in the return.'),
  ('intervention', 'intermediate', 'final', null, 40, 'Taken in the wrong place, one part of the working order poisons a conclusion while leaving all the arithmetic downstream of it correct. Which part?', '["Screening the well, since a verdict reached before the diagnosis is read carries no mechanism id behind it.", "Setting the window, since every slope, span and verdict after it is computed correctly on whatever window was chosen.", "Counting the samples, since a history under six samples is refused and nothing downstream of it runs at all.", "Pricing the alternative, since a multiplier taken before the skin is confirmed carries a wrong before-skin forward into everything after it."]'::jsonb, 1, 'The dial moves the derivative slope by 0.370920348 while the margin deciding the spend is 0.142132492322, and no later step can recover the choice.'),
  ('intervention', 'intermediate', 'final', null, 41, 'What is the one limit this whole course rests on?', '["For a power-law history the ratio and its derivative carry the same log-log slope, so only steepness separates displacement from channelling.", "A log-log slope cannot be fitted where any value is zero or negative, so a ratio that has turned back down cannot be read on the plot at all.", "A late window has to sit in boundary-dominated flow, and there is nothing anywhere in the module that tests whether the one it chose does.", "A fit quality below 0.5 as a fraction is refused, so a scattered history cannot produce a mechanism."]'::jsonb, 0, 'The engine concedes it in its own note, and it is why a boundary of 1.3 and a band of 0.25 are choices about where to cut.'),
  ('intervention', 'intermediate', 'final', null, 42, 'A colleague asks which of your numbers an independent oracle has confirmed. What is the answer?', '["The mechanism and the verdict, since the published file carries a labelled history for each of the four.", "The window start, since the oracle reads its own late window at series[20:] and the engine reproduces it.", "The log-log slope, by the median of every pairwise slope, and the skin multiplier, by a full radial Darcy rate in SI.", "All of them, since the published power law is reproduced to a difference of 0.0000e+0 on a published slope of 1.350000000000."]'::jsonb, 2, 'Everything that returns a verdict is asserted against nothing, so a mechanism, a confidence and a block reason are the engine''s own claims.');
